import {
  afterAll,
  beforeAll,
  beforeEach,
  describe,
  expect,
  it,
  vi,
} from "vitest";
import { randomUUID } from "node:crypto";
import { Client } from "pg";
import { PrismaClient } from "@/generated/prisma/client";
import { PrismaPg } from "@prisma/adapter-pg";
import {
  createIsolatedDatabase,
  databaseTestsEnabled,
} from "./helpers/foundation-db";
import { provisionAdminRole } from "../scripts/provision-admin-db";
import { provisionOperator } from "../scripts/bootstrap-admin";
const boundary = vi.hoisted(() => ({
  db: null as unknown as PrismaClient,
  auth: vi.fn(),
}));
vi.mock("@/auth", () => ({ auth: boundary.auth }));
vi.mock("@/lib/admin/db", () => ({ adminDb: () => boundary.db }));
vi.mock("@/lib/db", () => ({ db: {} }));
import {
  changeOverride,
  changeSuspension,
  changeControl,
} from "@/lib/admin/mutations";
import {
  listUsers,
  getAdminUser,
  listAudit,
  getAdminControl,
  effectivePlanSql,
} from "@/lib/admin/queries";
import { getEffectivePlan } from "@/lib/entitlements";
import { adminUserSelect } from "@/lib/admin/projections";
import { Prisma } from "@/generated/prisma/client";

describe.runIf(databaseTestsEnabled)(
  "restricted single operator database boundary",
  () => {
    let fixture: Awaited<ReturnType<typeof createIsolatedDatabase>>,
      owner: PrismaClient,
      restricted: Client,
      role: string;
    const actor = randomUUID(),
      subject = "FAKE-SUBJECT-DO-NOT-EXPOSE",
      token = "FAKE-REFRESH-TOKEN-DO-NOT-EXPOSE";
    beforeAll(async () => {
      fixture = await createIsolatedDatabase();
      for (const m of fixture.migrations) await fixture.apply(m);
      role = "admin_" + randomUUID().replaceAll("-", "");
      const url = new URL(fixture.url);
      url.username = role;
      url.password = randomUUID() + randomUUID();
      await provisionAdminRole(fixture.client, url.toString(), fixture.schema);
      owner = new PrismaClient({
        adapter: new PrismaPg(
          { connectionString: fixture.url },
          { schema: fixture.schema },
        ),
        log: [],
      });
      boundary.db = new PrismaClient({
        adapter: new PrismaPg(
          { connectionString: url.toString() },
          { schema: fixture.schema },
        ),
        log: [],
      });
      restricted = new Client({ connectionString: url.toString() });
      await restricted.connect();
      await owner.user.create({
        data: {
          id: actor,
          email: `${actor}@example.test`,
          googleId: subject,
          encryptedRefreshToken: token,
          usageBackfillVersion: 1,
        },
      });
      await provisionOperator(fixture.client, actor, subject);
    }, 30000);
    beforeEach(async () => {
      boundary.auth.mockResolvedValue({
        user: { id: actor },
        adminAuthAt: Math.floor(Date.now() / 1000),
        adminAuthUserId: actor,
      });
      await owner.rateLimitBucket.deleteMany({});
    });
    afterAll(async () => {
      await restricted?.end();
      await boundary.db?.$disconnect();
      await owner?.$disconnect();
      await fixture?.cleanup();
      if (role) {
        const c = new Client({ connectionString: process.env.DATABASE_URL });
        await c.connect();
        await c.query(`DROP OWNED BY "${role}"`);
        await c.query(`DROP ROLE IF EXISTS "${role}"`);
        await c.end();
      }
    });
    async function user(
      data: Prisma.UserCreateInput = { email: `${randomUUID()}@example.test` },
    ) {
      return owner.user.create({ data: { usageBackfillVersion: 1, ...data } });
    }
    it("denies all forbidden tables and columns while permitting explicit metadata", async () => {
      for (const sql of [
        'SELECT "encryptedRefreshToken" FROM "User"',
        'SELECT "googleId" FROM "User"',
        'SELECT * FROM "Contact"',
        'SELECT * FROM "Template"',
        'SELECT * FROM "Attachment"',
        'SELECT * FROM "BillingWebhookEvent"',
        'SELECT body FROM "Send"',
        'SELECT subject FROM "Send"',
        'SELECT "gmailMessageId" FROM "Send"',
        'SELECT before FROM "AdminAuditLog"',
        'UPDATE "User" SET "isAdmin"=false',
        'DELETE FROM "AdminAuditLog"',
        'TRUNCATE "AdminAuditLog"',
      ])
        await expect(restricted.query(sql)).rejects.toMatchObject({
          code: "42501",
        });
      expect(
        (
          await restricted.query('SELECT id,email FROM "User" WHERE id=$1', [
            actor,
          ])
        ).rowCount,
      ).toBe(1);
    });
    it("atomically bootstraps one operator, validates subject, and supports offline audited revocation", async () => {
      const other = await user({
        email: `${randomUUID()}@example.test`,
        googleId: "other-subject",
      });
      await expect(
        provisionOperator(fixture.client, other.id, "wrong"),
      ).rejects.toThrow("ADMIN_BOOTSTRAP_DENIED");
      await expect(
        provisionOperator(fixture.client, other.id, "other-subject"),
      ).rejects.toThrow("ADMIN_BOOTSTRAP_DENIED");
      await provisionOperator(fixture.client, actor, subject, true);
      expect(await listUsers({}).catch((e) => e.code)).toBe("DENIED");
      const second = new Client({ connectionString: fixture.url });
      await second.connect();
      const results = await Promise.allSettled([
        provisionOperator(fixture.client, actor, subject),
        provisionOperator(second, other.id, "other-subject"),
      ]);
      await second.end();
      expect(results.filter((r) => r.status === "fulfilled")).toHaveLength(1);
      const admin = await owner.user.findFirstOrThrow({
        where: { isAdmin: true },
        select: { id: true },
      });
      if (admin.id !== actor) {
        await provisionOperator(
          fixture.client,
          other.id,
          "other-subject",
          true,
        );
        await provisionOperator(fixture.client, actor, subject);
      }
      expect(
        (await listAudit({ action: "ADMIN_REVOKED" })).events.length,
      ).toBeGreaterThan(0);
    });
    it("serializes duplicate mutation requests, rejects conflicting reuse, and charges every attempt", async () => {
      const target = await user(),
        requestId = randomUUID(),
        input = {
          targetId: target.id,
          plan: "PAID",
          startsAt: null,
          expiresAt: null,
          reasonCode: "SUPPORT",
          requestId,
          confirmation: false,
        };
      expect(
        await Promise.all([changeOverride(input), changeOverride(input)]),
      ).toEqual([
        { ok: true, requestId },
        { ok: true, requestId },
      ]);
      expect(
        await changeOverride({ ...input, plan: "FREE", confirmation: true }),
      ).toEqual({ ok: false, code: "CONFLICT" });
      expect(await owner.adminAuditLog.count({ where: { requestId } })).toBe(1);
      expect(
        (
          await owner.rateLimitBucket.findUniqueOrThrow({
            where: { scope_operation: { scope: actor, operation: "admin" } },
          })
        ).admissions.length,
      ).toBe(3);
      const u = await owner.user.findUniqueOrThrow({
        where: { id: target.id },
      });
      expect(+u.planOverrideExpiresAt! - +u.planOverrideStartsAt!).toBe(
        30 * 86400000,
      );
      expect(u.plan).toBe("FREE");
    });
    it("requires billing acknowledgement and retains admissions after audit failure", async () => {
      const target = await user(),
        input = {
          targetId: target.id,
          plan: "FREE",
          startsAt: null,
          expiresAt: null,
          reasonCode: "SUPPORT",
          requestId: randomUUID(),
          confirmation: false,
        };
      expect(await changeOverride(input)).toEqual({
        ok: false,
        code: "INVALID_INPUT",
      });
      await fixture.client.query(
        `CREATE FUNCTION reject_admin_test() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'FAKE-ERROR-TOKEN-CONTENT'; END $$; CREATE TRIGGER reject_admin_test BEFORE INSERT ON "AdminAuditLog" FOR EACH ROW EXECUTE FUNCTION reject_admin_test()`,
      );
      try {
        expect(await changeOverride({ ...input, confirmation: true })).toEqual({
          ok: false,
          code: "UNAVAILABLE",
        });
        expect(
          (await owner.user.findUniqueOrThrow({ where: { id: target.id } }))
            .planOverride,
        ).toBeNull();
        expect(
          (
            await owner.rateLimitBucket.findUniqueOrThrow({
              where: { scope_operation: { scope: actor, operation: "admin" } },
            })
          ).admissions.length,
        ).toBe(2);
      } finally {
        await fixture.client.query(
          'DROP TRIGGER reject_admin_test ON "AdminAuditLog"; DROP FUNCTION reject_admin_test()',
        );
      }
    });
    it("limits every mutation attempt to twenty per minute including replays", async () => {
      const target = await user(),
        input = {
          targetId: target.id,
          suspended: false,
          reasonCode: "OPERATIONS",
          requestId: randomUUID(),
        };
      for (let i = 0; i < 20; i++)
        expect(
          (
            await changeSuspension({
              ...input,
              requestId: i === 0 ? input.requestId : randomUUID(),
            })
          ).ok,
        ).toBe(true);
      expect(
        await changeSuspension({ ...input, requestId: randomUUID() }),
      ).toMatchObject({
        ok: false,
        code: "RATE_LIMITED",
        retryAfter: expect.any(Number),
      });
      expect(await changeSuspension(input)).toMatchObject({
        ok: false,
        code: "RATE_LIMITED",
        retryAfter: expect.any(Number),
      });
    });
    it("cancels only unattempted work, releases reservations, preserves uncertain evidence and never resumes cancelled sends", async () => {
      const u = await user(),
        template = await owner.template.create({
          data: {
            userId: u.id,
            name: "SECRET-TEMPLATE",
            subject: "SECRET-SUBJECT",
            body: "SECRET-BODY",
          },
        }),
        contact = await owner.contact.create({
          data: {
            userId: u.id,
            name: "SECRET-CONTACT",
            email: `${randomUUID()}@private.test`,
          },
        }),
        campaign = await owner.campaign.create({
          data: { userId: u.id, templateId: template.id, status: "SENDING" },
        });
      const now = new Date(),
        day = await owner.usagePeriod.create({
          data: {
            userId: u.id,
            key: "day:test",
            kind: "DAILY",
            startsAt: new Date(+now - 10000),
            endsAt: new Date(+now + 86400000),
            operationalEndsAt: new Date(+now + 86400000),
          },
        }),
        month = await owner.usagePeriod.create({
          data: {
            userId: u.id,
            key: "month:test",
            kind: "MONTHLY",
            startsAt: day.startsAt,
            endsAt: day.endsAt,
            operationalEndsAt: day.endsAt,
          },
        });
      const sends = [];
      for (const status of ["RESERVED", "ATTEMPTING", "UNCERTAIN"] as const) {
        const s = await owner.send.create({
          data: {
            campaignId: campaign.id,
            contactId: contact.id,
            body: "SECRET-BODY",
            deliveryState: status === "RESERVED" ? "READY" : status,
            attemptedAt: status === "RESERVED" ? null : now,
          },
        });
        sends.push(s);
        await owner.usageReservation.create({
          data: {
            userId: u.id,
            deliveryKey: s.id,
            sendId: s.id,
            dailyPeriodId: day.id,
            monthlyPeriodId: month.id,
            status,
            chargedAt: status === "RESERVED" ? null : now,
            claimToken: status === "RESERVED" ? null : randomUUID(),
            leaseExpiresAt:
              status === "RESERVED" ? null : new Date(+now + 60000),
          },
        });
      }
      expect(
        (
          await changeSuspension({
            targetId: u.id,
            suspended: true,
            reasonCode: "ABUSE",
            requestId: randomUUID(),
          })
        ).ok,
      ).toBe(true);
      expect(
        (await owner.send.findUniqueOrThrow({ where: { id: sends[0].id } }))
          .status,
      ).toBe("CANCELLED");
      expect(
        (
          await owner.usageReservation.findUniqueOrThrow({
            where: { sendId: sends[0].id },
          })
        ).status,
      ).toBe("RELEASED");
      expect(
        (await owner.usagePeriod.findUniqueOrThrow({ where: { id: month.id } }))
          .reserved,
      ).toBe(2);
      for (const s of sends.slice(1))
        expect(
          (await owner.send.findUniqueOrThrow({ where: { id: s.id } })).status,
        ).toBe("QUEUED");
      expect(
        (
          await changeSuspension({
            targetId: u.id,
            suspended: false,
            reasonCode: "SUPPORT",
            requestId: randomUUID(),
          })
        ).ok,
      ).toBe(true);
      expect(
        (await owner.send.findUniqueOrThrow({ where: { id: sends[0].id } }))
          .status,
      ).toBe("CANCELLED");
      expect(
        await changeSuspension({
          targetId: actor,
          suspended: true,
          reasonCode: "SUPPORT",
          requestId: randomUUID(),
        }),
      ).toEqual({ ok: false, code: "DENIED" });
      const serialized = JSON.stringify([
        await getAdminUser(u.id),
        await listUsers({}),
        await listAudit({ targetId: u.id }),
      ]);
      for (const secret of [
        token,
        subject,
        "SECRET-TEMPLATE",
        "SECRET-SUBJECT",
        "SECRET-BODY",
        "SECRET-CONTACT",
        "private.test",
      ])
        expect(serialized).not.toContain(secret);
    });
    it("uses optimistic global controls and blocks updates while a claim holds its shared lock", async () => {
      const control = await getAdminControl(),
        claim = new Client({ connectionString: fixture.url });
      await claim.connect();
      await claim.query("BEGIN");
      await claim.query(
        'SELECT "sendingEnabled" FROM "SystemControl" WHERE key=\'global\' FOR SHARE',
      );
      let done = false;
      const pending = changeControl({
        sendingEnabled: !control.sendingEnabled,
        expectedUpdatedAt: control.updatedAt,
        reasonCode: "OPERATIONS",
        requestId: randomUUID(),
      }).then((r) => {
        done = true;
        return r;
      });
      // Wait until pg reports the update blocked, rather than relying on timer ordering.
      for (let i = 0; i < 100; i++) {
        const r = await fixture.client.query(
          "SELECT 1 FROM pg_stat_activity WHERE usename=$1 AND wait_event_type='Lock'",
          [role],
        );
        if (r.rowCount) break;
        await new Promise((r) => setTimeout(r, 10));
      }
      try {
        expect(done).toBe(false);
      } finally {
        await claim.query("ROLLBACK");
        await claim.end();
      }
      expect((await pending).ok).toBe(true);
      expect(
        await changeControl({
          sendingEnabled: control.sendingEnabled,
          expectedUpdatedAt: control.updatedAt,
          reasonCode: "OPERATIONS",
          requestId: randomUUID(),
        }),
      ).toEqual({ ok: false, code: "CONFLICT" });
    });
    it("matches effective-plan SQL to entitlement resolution at boundaries before cursor pagination", async () => {
      const at = new Date(),
        past = new Date(+at - 10000),
        future = new Date(+at + 10000);
      const variants: Partial<Prisma.UserCreateInput>[] = [
        {},
        {
          plan: "PAID",
          subscriptionStatus: "ACTIVE",
          dodoSubscriptionId: "",
          currentPeriodStart: past,
          currentPeriodEnd: future,
        },
        {
          plan: "PAID",
          subscriptionStatus: "ACTIVE",
          dodoSubscriptionId: randomUUID(),
          currentPeriodStart: past,
          currentPeriodEnd: future,
        },
        {
          plan: "PAID",
          subscriptionStatus: "ACTIVE",
          dodoSubscriptionId: randomUUID(),
          currentPeriodStart: past,
          currentPeriodEnd: at,
        },
        {
          plan: "PAID",
          subscriptionStatus: "PAST_DUE",
          dodoSubscriptionId: randomUUID(),
          currentPeriodStart: past,
          currentPeriodEnd: at,
          gracePeriodEnd: future,
        },
        { grandfatheredUntil: at },
        { grandfatheredUntil: future },
        {
          planOverride: "PAID",
          planOverrideStartsAt: past,
          planOverrideExpiresAt: at,
          planOverrideReason: "SUPPORT",
        },
        {
          planOverride: "PAID",
          planOverrideStartsAt: at,
          planOverrideExpiresAt: future,
          planOverrideReason: "SUPPORT",
        },
        {
          planOverride: "FREE",
          planOverrideStartsAt: past,
          planOverrideExpiresAt: future,
          planOverrideReason: "SUPPORT",
          grandfatheredUntil: future,
        },
      ];
      for (const data of variants) {
        const u = await user({
          email: `${randomUUID()}@boundary.test`,
          ...data,
        });
        const projected = await owner.user.findUniqueOrThrow({
          where: { id: u.id },
          select: adminUserSelect,
        });
        const rows = await boundary.db.$queryRaw<
          { effective: string }[]
        >`SELECT ${effectivePlanSql(at)} AS effective FROM "User" WHERE id=${u.id}`;
        expect(rows[0].effective).toBe(getEffectivePlan(projected, at));
      }
      const stamp = new Date("2026-10-01Z");
      for (let i = 0; i < 54; i++)
        await user({
          email: `${randomUUID()}@pagination.test`,
          name: "Mixed Case Search",
          createdAt: stamp,
          planOverride: "PAID",
          planOverrideStartsAt: past,
          planOverrideExpiresAt: future,
          planOverrideReason: "SUPPORT",
        });
      const first = await listUsers({ search: "mixed CASE", plan: "PAID" }),
        second = await listUsers({
          search: "mixed CASE",
          plan: "PAID",
          cursor: first.nextCursor!,
        });
      expect(first.users).toHaveLength(50);
      expect(second.users).toHaveLength(4);
      expect(
        new Set([...first.users, ...second.users].map((u) => u.id)).size,
      ).toBe(54);
    });
    it("does not write during reporting and preserves consumption through override removal", async () => {
      const target = await user(),
        at = new Date();
      await owner.usageImportEvidence.create({
        data: {
          userId: target.id,
          sourceKey: "proof",
          deliveryKey: randomUUID(),
          chargedAt: at,
          timestampSource: "sentAt",
        },
      });
      const input = {
        targetId: target.id,
        plan: "PAID",
        startsAt: null,
        expiresAt: null,
        reasonCode: "SUPPORT",
        requestId: randomUUID(),
        confirmation: false,
      };
      expect((await changeOverride(input)).ok).toBe(true);
      const periodCount = await owner.usagePeriod.count({
        where: { userId: target.id },
      });
      expect((await getAdminUser(target.id))?.usage.monthly?.sent).toBe(1);
      expect(
        await owner.usagePeriod.count({ where: { userId: target.id } }),
      ).toBe(periodCount);
      expect(
        (
          await changeOverride({
            ...input,
            plan: null,
            requestId: randomUUID(),
          })
        ).ok,
      ).toBe(true);
      expect((await getAdminUser(target.id))?.usage.monthly?.sent).toBe(1);
    });
  },
);
